-- +goose Up
CREATE TYPE "transaction_type" AS ENUM (
  'income',
  'expense'
);

CREATE TABLE "users" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "username" varchar UNIQUE NOT NULL,
  "password_hash" varchar,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_at" timestamptz NOT NULL DEFAULT (now())
);

CREATE TABLE "accounts" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" integer NOT NULL,
  "name" varchar NOT NULL,
  "currency" varchar(3) NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_at" timestamptz NOT NULL DEFAULT (now())
);

CREATE TABLE "groups" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar NOT NULL,
  "created_by" integer NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_at" timestamptz NOT NULL DEFAULT (now())
);

CREATE TABLE "group_members" (
  "group_id" integer NOT NULL,
  "user_id" integer NOT NULL,
  "joined_at" timestamptz NOT NULL DEFAULT (now()),
  PRIMARY KEY ("group_id", "user_id")
);

CREATE TABLE "transactions" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "account_id" integer NOT NULL,
  "group_id" integer,
  "type" transaction_type NOT NULL,
  "amount" bigint NOT NULL CHECK ("amount" > 0),
  "description" varchar,
  "occurred_at" timestamptz NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_at" timestamptz NOT NULL DEFAULT (now())
);

CREATE TABLE "balances" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "account_id" integer NOT NULL,
  "transaction_id" integer UNIQUE NOT NULL,
  "amount" bigint NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT (now())
);

-- Index'ler
CREATE UNIQUE INDEX ON "accounts" ("user_id", "name");
CREATE INDEX ON "transactions" ("account_id");
CREATE INDEX ON "transactions" ("group_id");
CREATE INDEX ON "balances" ("account_id", "id");
CREATE INDEX ON "group_members" ("user_id");

COMMENT ON COLUMN "transactions"."amount" IS 'kuruş cinsinden, her zaman pozitif';
COMMENT ON COLUMN "balances"."amount" IS 'işlemden sonraki bakiye, kuruş';

-- Foreign key'ler
